reversal.fixed_text:
let self_dir = self.dir;
let start_node = self.start_node;
(&mut self.iter)
    .filter_map(move |&(n, dir)| if dir == self_dir || n == start_node {
        Some(n)
    } else { None })
    .next()

reversal.parent_text:
let self_dir = self.dir;
(&mut self.iter)
    .filter_map(move |&(n, dir)| if dir == self_dir {
        Some(n)
    } else { None })
    .next()
